export const storageName=b=>({barn:'\u8C37\u7269\u4E0E\u52A0\u5DE5\u4ED3\u5E93',silo:'\u4E30\u6536\u7B52\u4ED3',warehouse:'\u96C6\u914D\u8D27\u4ED3'}[b.type]||'\u4ED3\u5E93');
